customMethods.script:
# Bulk open (backlog 3.4). bulkOpenDraft is the authoritative per-cavity
# entry map: the repeater rows are input-only embeds and can only report
# upward via the page-scoped bulkOpenRowChanged message, so nothing is
# ever read back out of the repeater here.
draft = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.bulkOpenDraft) or {}
tool = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.activeTool) or {}
cell = BlueRidge.Common.Util.extractQualifiedValues(self.session.custom.cell) or {}
rows = []
for key in draft.keys():
	d = draft.get(key) or {}
	rows.append({"toolCavityId": d.get("toolCavityId"), "itemId": d.get("itemId"), "scannedLtt": d.get("scannedLtt")})
term = None
try:
	term = self.session.custom.terminal.terminalLocationId
except:
	term = None
res = BlueRidge.Workorder.DieCast.submitBulkOpen(rows, tool.get("ToolId"), cell.get("locationId"), self.session.custom.appUserId, term) or {}
# Per-row outcomes live on the VIEW, not inside the rows: the repeater's
# instances transform overlays them, so they survive the rebuild below.
self.view.custom.bulkOpenResult = res.get("Rows") or {}
if res.get("Rejected"):
	# A batch gate fired -- NOTHING was written, so the operator's entries
	# stay exactly as they are and no rebuild happens.
	BlueRidge.Common.Notify.toast("Nothing opened", res.get("Message") or "", "warning")
	return res
# Partial submission: keep only the rows that did NOT open, so the operator
# re-enters the failures alone and never a cavity that already succeeded.
rowResults = res.get("Rows") or {}
kept = {}
for key in draft.keys():
	if (rowResults.get(key) or {}).get("state") == "ok":
		continue
	kept[key] = draft.get(key) or {}
self.view.custom.bulkOpenDraft = kept
self.view.custom.bulkOpenPendingCount = BlueRidge.Workorder.DieCast.bulkOpenPending(kept)
level = "success"
if res.get("Failed"):
	level = "warning" if res.get("Opened") else "error"
BlueRidge.Common.Notify.toast("Bulk open", res.get("Message") or "", level)
self.view.custom.refreshToken = (self.view.custom.refreshToken or 0) + 1
# D9: ONE CRT notice per SUBMIT, naming every basket that opened CRT --
# never one dialog per cavity, which trains operators to dismiss dialogs.
# LAST, after the refresh bump: every basket has already committed.
BlueRidge.Common.Ui.crtNotice(res.get("CrtLots"), res.get("Opened"))
return res

# Wipe every operator entry AND the last submission's per-row results, then
# rebuild the rows from the live cavity/open-basket state.
self.view.custom.bulkOpenDraft = {}
self.view.custom.bulkOpenResult = {}
self.view.custom.bulkOpenPendingCount = 0
self.view.custom.refreshToken = (self.view.custom.refreshToken or 0) + 1

import java.lang
# quiet=True is the die-wide-driven re-proposal; quiet=False is the
# operator pressing Compute, which is a FRESH START and therefore blanks
# the list first so every row sub-view REMOUNTS (that is what clears a
# row's scrap lines and its operator-entered Good override).
tool = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.activeTool) or {}
toolId = tool.get("ToolId")
if toolId is None:
	if not quiet:
		BlueRidge.Common.Notify.toast("No die mounted", "Mount a tool at this cell before reconciling a shift.", "warning")
	return
shiftId = self.view.custom.selectedShiftId
if shiftId is None:
	if not quiet:
		BlueRidge.Common.Notify.toast("Select a shift", "Pick the shift this output is reported against.", "warning")
	return
gross = BlueRidge.Common.Util.toIntOrNone(self.view.custom.counterReading)
if gross is None:
	if not quiet:
		BlueRidge.Common.Notify.toast("Enter the counter reading", "Type the press counter reading before computing.", "warning")
	return
# the PRESS -- watermarks are scoped by it. Resolved exactly as
# submitShiftOutput does; it is NOT in scope in this method otherwise.
cell = BlueRidge.Common.Util.extractQualifiedValues(self.session.custom.cell) or {}
dw = BlueRidge.Common.Util.toIntOrNone(self.view.custom.dieWideShots) or 0
try:
	rows = BlueRidge.Workorder.DieCast.getShiftOutputBreakdown(
		toolId, shiftId, gross, cell.get("locationId"), dieWideShots=dw)
except (Exception, java.lang.Exception) as e:
	BlueRidge.Common.Util.log("computeBreakdown failed: %s" % str(e), level="warn")
	if not quiet:
		BlueRidge.Common.Notify.toast("Could not compute", "%s" % str(e), "error")
	return
# NO filtering. A basket released mid-shift must stay on screen so its
# scrap can be entered at shift end, and proc v2.1+ also returns cavities
# with NO basket so a pending one is visible and scrappable.
if not quiet:
	self.view.custom.breakdown = []
	self.view.custom.breakdownEntries = {}
self.view.custom.breakdown = rows
self.recomputeTotals()
if not rows and not quiet:
	BlueRidge.Common.Notify.toast("No cavities", "This die has no cavities configured.", "warning")

total = 0
for r in (BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.dieWideLines) or []):
	r = r or {}
	if r.get("defectCodeId") is None:
		continue
	q = BlueRidge.Common.Util.toIntOrNone(r.get("shots"))
	if q:
		total += q
self.view.custom.dieWideShots = total

# D6: shot loss no longer fires its own proc call the instant it is typed;
# it rides the ONE Submit. DieCastShiftOutput_Record has always accepted
# lines and shotLoss in the same call.
out = []
for r in (BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.dieWideLines) or []):
	r = r or {}
	d = r.get("defectCodeId")
	q = BlueRidge.Common.Util.toIntOrNone(r.get("shots"))
	if d is not None and q:
		out.append({"defectCodeId": d, "quantity": q})
return out
